// Deliberately at global scope: EnemyCommands.cpp nests its namespaces (th11::th11), so a declaration
// inside namespace th11 would not be found by unqualified lookup from there. title_noop_opcode takes the
// title number so one build can be checked against every other title's table; runtime_noop_opcode is the
// one the handlers call and follows kPortTitle from PortTitle.hpp.
inline bool title_noop_opcode(uint32_t title,uint16_t opcode)noexcept{
    const uint8_t* bits=nullptr;uint32_t first=0,last=0;
    switch(title){
    case 12:bits=th12_bits;first=th12_first;last=th12_last;break;
    case 13:bits=th13_bits;first=th13_first;last=th13_last;break;
    case 14:bits=th14_bits;first=th14_first;last=th14_last;break;
    case 16:bits=th16_bits;first=th16_first;last=th16_last;break;
    case 17:bits=th17_bits;first=th17_first;last=th17_last;break;
    case 18:bits=th18_bits;first=th18_first;last=th18_last;break;
    default:return false;
    }
    if(opcode>last)return true;
    if(opcode<first)return false;
    const uint32_t index=uint32_t(opcode)-first;
    return ((bits[index>>3]>>(index&7))&1)!=0;
}

#include "PortTitle.hpp"
inline bool runtime_noop_opcode(uint16_t opcode)noexcept{return title_noop_opcode(kPortTitle,opcode);}
